   368→  private accumulationSystems: AccumulationSystem[] = [];
   369→  private spiralSystems: SpiralSystem[] = [];
   370→
   371→  /**
   372→   * Register a system
   373→   */
   374→  register(system: SimulationSystem): void {
   375→    this.systems.set(system.id, system);
   376→
   377→    // Track by type for specialized operations
   378→    if (this.isAccumulationSystem(system)) {
   379→      this.accumulationSystems.push(system);
   380→    }
   381→    if (this.isSpiralSystem(system)) {
   382→      this.spiralSystems.push(system);
   383→    }
   384→  }
   385→
   386→  /**
   387→   * Initialize all registered systems
   388→   */
   389→  initializeAll(): Record<string, any> {
   390→    const states: Record<string, any> = {};
   391→
   392→    for (const [id, system] of this.systems) {
   393→      states[id] = system.initialize();
   394→    }
   395→
   396→    return states;
   397→  }
   398→
   399→  /**
   400→   * Update all systems in registered order
   401→   */
   402→  updateAll(globalState: GameState): void {
