   704→```typescript
   705→import { GameState, GameEvent } from '@/types/game';
   706→
   707→/**
   708→ * Represents a single simulation phase
   709→ */
   710→export interface SimulationPhase {
   711→  readonly name: string;
   712→  readonly order: number;
   713→  execute(state: GameState, rng: () => number): PhaseResult;
   714→}
   715→
   716→export interface PhaseResult {
   717→  events: GameEvent[];
   718→  // Other metadata as needed
   719→}
   720→
   721→/**
   722→ * Orchestrates simulation phases in correct order
   723→ */
   724→export class PhaseOrchestrator {
   725→  private phases: SimulationPhase[] = [];
   726→
   727→  /**
   728→   * Register a phase
   729→   */
   730→  registerPhase(phase: SimulationPhase): void {
   731→    this.phases.push(phase);
   732→    // Sort by order after each registration
   733→    this.phases.sort((a, b) => a.order - b.order);
   734→  }
   735→
   736→  /**
   737→   * Execute all phases in order
   738→   */
   739→  executeAll(state: GameState, rng: () => number): GameEvent[] {
   740→    const allEvents: GameEvent[] = [];
   741→
   742→    for (const phase of this.phases) {
   743→      const result = phase.execute(state, rng);
   744→      allEvents.push(...result.events);
   745→    }
   746→
   747→    return allEvents;
   748→  }
   749→
   750→  /**
   751→   * Get phase execution order (for debugging)
   752→   */
   753→  getExecutionOrder(): string[] {
   754→    return this.phases.map(p => `${p.order}: ${p.name}`);
   755→  }
   756→}
   757→```
