   905→
   906→```typescript
   907→import { produce, Draft } from 'immer';
   908→import { GameState } from '@/types/game';
   909→
   910→/**
   911→ * Type-safe state updater using Immer
   912→ */
   913→export function updateState(
   914→  state: GameState,
   915→  updater: (draft: Draft<GameState>) => void
   916→): GameState {
   917→  return produce(state, updater);
   918→}
   919→
   920→/**
   921→ * Update subsystem within state
   922→ */
   923→export function updateSubsystem<K extends keyof GameState>(
   924→  state: GameState,
   925→  key: K,
   926→  updater: (draft: Draft<GameState[K]>) => void
   927→): GameState {
   928→  return produce(state, draft => {
   929→    updater(draft[key]);
   930→  });
   931→}
   932→```
