function createCorporateAIs(count: number): AIAgent[] {
  const agents: AIAgent[] = [];
  for (let i = 0; i < count; i++) {
    const alignment = 0.75 + Math.random() * 0.15;
    agents.push(createAIAgent(
      `corporate_${i}`,
      `Corporate-${i}`,
      0.05 + i * 0.01,
      alignment,
      i * 1.5
    ));
  }
  return agents;
}

